file /tmp/boys_s5_vk.mp4 && ffprobe -v quiet -print_format json -show_streams /tmp/boys_s5_vk.mp4 2>&1 | python3 -c "
import sys,json
try:
    d=json.load(sys.stdin)
    for s in d.get('streams',[]):
        c=s.get('codec_type',''), s.get('codec_name',''), s.get('width',''), s.get('height','')
        print(f'  Stream: {c[0]} {c[1]} {c[2]}x{c[3]}')
except: print('not valid video')
"
